def choose_move(observation):
    def clamp_step(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos(obj, default=None):
        if isinstance(obj, (list, tuple)) and len(obj) >= 2:
            return obj[0], obj[1]
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def step_away(a, b):
        return [clamp_step(a[0] - b[0]), clamp_step(a[1] - b[1])]

    env = observation.get("environment_name", "resource_collection")
    self_pos = pos(observation.get("self_position"), (0, 0))
    opp_pos = pos(observation.get("opponent_position"), self_pos)
    w = observation.get("grid_width", 0)
    h = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)

        corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        corners = [c for c in corners if c[0] >= 0 and c[1] >= 0]
        if corners:
            target = max(corners, key=lambda c: (manhattan(c, opp_pos), -manhattan(c, self_pos)))
            return step_toward(self_pos, target)
        return step_away(self_pos, opp_pos)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        if targets:
            best = min(targets, key=lambda item: (manhattan(item, self_pos), manhattan(item, opp_pos)))
            return step_toward(self_pos, best)

        center = ((w - 1) // 2 if w else self_pos[0], (h - 1) // 2 if h else self_pos[1])
        own = observation.get("self_territory") or []
        if own:
            far = max(own, key=lambda item: manhattan(item, center))
            return step_toward(self_pos, far)
        return step_toward(self_pos, center)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        best = min(resources, key=lambda item: (manhattan(item, self_pos), manhattan(item, opp_pos)))
        move = step_toward(self_pos, best)
        if move == [0, 0] and opp_pos != self_pos and manhattan(opp_pos, best) <= 1:
            return step_away(self_pos, opp_pos)
        return move

    # Default: move toward opponent if close, else toward center.
    if opp_pos != self_pos and manhattan(self_pos, opp_pos) <= 2:
        return step_away(self_pos, opp_pos)
    center = ((w - 1) // 2 if w else self_pos[0], (h - 1) // 2 if h else self_pos[1])
    return step_toward(self_pos, center)

